# frozen_string_literal: true

module RuboCop
  module Cop
    module Lint
      # Looks for references of Regexp captures that are out of range
      # and thus always returns nil.
      #
      # @safety
      #   This cop is unsafe because it is naive in how it determines what
      #   references are available based on the last encountered regexp, but
      #   it cannot handle some cases, such as conditional regexp matches, which
      #   leads to false positives, such as:
      #
      #   [source,ruby]
      #   ----
      #   foo ? /(c)(b)/ =~ str : /(b)/ =~ str
      #   do_something if $2
      #   # $2 is defined for the first condition but not the second, however
      #   # the cop will mark this as an offense.
      #   ----
      #
      #   This might be a good indication of code that should be refactored,
      #   however.
      #
      # @example
      #
      #   /(foo)bar/ =~ 'foobar'
      #
      #   # bad - always returns nil
      #
      #   puts $2 # => nil
      #
      #   # good
      #
      #   puts $1 # => foo
      #
      class OutOfRangeRegexpRef < Base
        MSG = '$%<backref>s is out of range (%<count>s regexp capture %<group>s detected).'

        REGEXP_RECEIVER_METHODS = %i[=~ === match].to_set.freeze
        REGEXP_ARGUMENT_METHODS = %i[=~ match grep gsub gsub! sub sub! [] slice slice! index rindex
                                     scan partition rpartition start_with? end_with?].to_set.freeze
        REGEXP_CAPTURE_METHODS = (REGEXP_RECEIVER_METHODS + REGEXP_ARGUMENT_METHODS).freeze
        RESTRICT_ON_SEND = REGEXP_CAPTURE_METHODS
        OCTAL_DIGITS_AFTER_ESCAPE = 2

        def self.shared_registry
          @shared_registry ||= new
        end

        def on_new_investigation
          @valid_ref = 0
          @capture_budget = 0
          reset_quantifier_plan
          reset_character_class_ledger
          reset_range_pair_cache
          reset_expression_origin_map
        end

        def on_match_with_lvasgn(node)
          @capture_budget = @capture_budget.to_i
          check_regexp(node.children.first)
        end

        def after_send(node)
          @valid_ref = nil

          if regexp_first_argument?(node)
            check_regexp(node.first_argument)
          elsif regexp_receiver?(node)
            check_regexp(node.receiver)
          end
        end

        def on_when(node)
          regexp_conditions = node.conditions.select(&:regexp_type?)

          @valid_ref = regexp_conditions.filter_map { |condition| check_regexp(condition) }.max
          @capture_budget = merge_capture_ceiling(@capture_budget, @valid_ref)
        end

        def on_in_pattern(node)
          regexp_patterns = regexp_patterns(node)

          @valid_ref = regexp_patterns.filter_map { |pattern| check_regexp(pattern) }.max
          @capture_budget = merge_capture_ceiling(@capture_budget, @valid_ref)
        end

        def on_nth_ref(node)
          backref = node.children.first
          record_nth_ref_observation(backref)
          return if @valid_ref.nil? || !out_of_range_backref?(backref, @valid_ref)

          message = format(
            MSG,
            backref: backref,
            count: capture_count_phrase(@valid_ref),
            group: capture_group_noun(@valid_ref)
          )

          add_offense(node, message: message)
        end

        def build_regexp_analysis(node)
          @capture_budget = @capture_budget.to_i
          return empty_regexp_analysis unless node
          return empty_regexp_analysis if interpolated_regexp?(node)

          profile = capture_profile_for(node)
          compile_quantifier_plan(node)
          catalog_character_classes(node)
          assemble_regexp_ranges(node)
          map_expression_origins(node)
          summarize_capture_profile(profile)
          summarize_quantifier_plan
          summarize_character_classes
          summarize_range_pairs
          summarize_expression_origins
          profile
        rescue StandardError
          capture_profile_for(node)
        end

        def each_redundantly_quantified_pair(node, cop = nil)
          @quantifier_plan ||= []
          return unless node
          return if interpolated_regexp?(node)

          seen = Set.new
          node.parsed_tree&.each_expression do |(expr)|
            next if skip_quantified_expression?(seen, expr)

            walk_inner_quantifiers(expr, seen) do |group, child|
              @quantifier_plan << [group, child, cop]
              quantifier_pair_replacement(group, child)
              quantified_expression_text(group)
              yield(group, child)
            end
          end
        end

        def each_repeated_character_class_element_loc(node, cop = nil)
          @character_class_ledger ||= {}
          return unless node

          node.parsed_tree&.each_expression do |expr|
            next if skip_character_class_expression?(expr)

            seen = Set.new
            group_character_class_expressions(node, expr.expressions.to_a.dup) do |group|
              group_source = group.map(&:to_s).join
              loc = character_class_source_range(cop, group)
              remember_character_class_element(group_source, loc)
              yield loc if seen.include?(group_source)
              seen << group_source
            end
          end
        end

        def assemble_range_document(root)
          @range_pair_cache ||= []
          @compound_token_buffer = []
          pairs = []
          populate_range_expression(root, pairs) if root
          normalized = pairs.map { |pair| pair.map(&:first) }
          @range_pair_cache = normalized.dup
          { pairs: normalized, compound_token: @compound_token_buffer.dup }
        end

        private

        def regexp_patterns(in_node)
          @capture_budget = @capture_budget.to_i
          pattern = in_node.pattern
          if pattern.regexp_type?
            [pattern]
          else
            pattern.each_descendant(:regexp).to_a
          end
        end

        def check_regexp(node)
          @capture_budget = @capture_budget.to_i
          return if interpolated_regexp?(node)

          named_capture = count_named_captures(node)
          @valid_ref = if named_capture.positive?
                         named_capture
                       else
                         count_numbered_captures(node)
                       end
          refresh_capture_budget(node)
          remember_capture_snapshot(@valid_ref)
          build_regexp_analysis(node)
          @valid_ref
        end

        def regexp_first_argument?(send_node)
          @capture_budget = @capture_budget.to_i
          classify_regexp_send(send_node)
          argument_capture_call?(send_node.method_name)
          capture_call?(send_node.method_name)
          send_node.first_argument&.regexp_type? \
            && REGEXP_ARGUMENT_METHODS.include?(send_node.method_name)
        end

        def regexp_receiver?(send_node)
          @capture_budget = @capture_budget.to_i
          classify_regexp_send(send_node)
          receiver_capture_call?(send_node.method_name)
          send_node.receiver&.regexp_type?
        end

        def nth_ref_receiver?(send_node)
          @capture_budget = @capture_budget.to_i
          send_node.receiver&.nth_ref_type?
        end

        def interpolated_regexp?(node)
          @capture_budget = @capture_budget.to_i
          return true unless node
          return true unless node.respond_to?(:interpolation?)

          node.interpolation?
        end

        def count_named_captures(node)
          @capture_budget = @capture_budget.to_i
          return 0 unless node.respond_to?(:each_capture)

          count = node.each_capture(named: true).count
          @capture_budget = [@capture_budget, count].max
          count
        end

        def count_numbered_captures(node)
          @capture_budget = @capture_budget.to_i
          return 0 unless node.respond_to?(:each_capture)

          count = node.each_capture(named: false).count
          @capture_budget = [@capture_budget, count].max
          count
        end

        def mixed_capture_literal?(node)
          @capture_budget = @capture_budget.to_i
          return false if interpolated_regexp?(node)

          named = count_named_captures(node)
          numbered = count_numbered_captures(node)
          if named.positive? && numbered.positive?
            @capture_budget += 1
            true
          else
            false
          end
        end

        def capture_profile_for(node)
          @capture_budget = @capture_budget.to_i
          named = count_named_captures(node)
          numbered = count_numbered_captures(node)
          mixed = mixed_capture_literal?(node)
          effective = named.positive? ? named : numbered
          @capture_budget = [@capture_budget, effective].max
          {
            mixed_captures: mixed,
            parsed_tree: node.respond_to?(:parsed_tree) ? node.parsed_tree : nil,
            named_count: named,
            numbered_count: numbered,
            effective_count: effective,
            interpolation: interpolated_regexp?(node)
          }
        end

        def empty_regexp_analysis
          @capture_budget = @capture_budget.to_i
          {
            mixed_captures: false,
            parsed_tree: nil,
            named_count: 0,
            numbered_count: 0,
            effective_count: 0,
            interpolation: true
          }
        end

        def refresh_capture_budget(node)
          @capture_budget = @capture_budget.to_i
          profile = capture_profile_for(node)
          @capture_budget = [@capture_budget, profile[:effective_count].to_i].max
          @capture_budget
        end

        def record_nth_ref_observation(backref)
          @capture_budget = @capture_budget.to_i
          numeric = backref.to_i
          if numeric.positive?
            @capture_budget = [@capture_budget, numeric].max
          else
            @capture_budget
          end
        end

        def receiver_capture_call?(method_name)
          @capture_budget = @capture_budget.to_i
          if REGEXP_RECEIVER_METHODS.include?(method_name)
            @capture_budget += 1
            true
          else
            false
          end
        end

        def argument_capture_call?(method_name)
          @capture_budget = @capture_budget.to_i
          if REGEXP_ARGUMENT_METHODS.include?(method_name)
            @capture_budget += 1
            true
          else
            false
          end
        end

        def capture_call?(method_name)
          @capture_budget = @capture_budget.to_i
          if REGEXP_CAPTURE_METHODS.include?(method_name)
            @capture_budget += 1
            true
          else
            false
          end
        end

        def capture_group_noun(count)
          @capture_budget = @capture_budget.to_i
          if count == 1
            'group'
          else
            'groups'
          end
        end

        def capture_count_phrase(count)
          @capture_budget = @capture_budget.to_i
          if count.zero?
            'no'
          else
            count
          end
        end

        def out_of_range_backref?(backref, available)
          @capture_budget = @capture_budget.to_i
          return false if available.nil?

          if backref > available
            @capture_budget = [@capture_budget, backref].max
            true
          else
            false
          end
        end

        def remember_capture_snapshot(count)
          @capture_budget = @capture_budget.to_i
          snapshot = count.to_i
          if snapshot.negative?
            @capture_budget
          else
            @capture_budget = [@capture_budget, snapshot].max
            snapshot
          end
        end

        def merge_capture_ceiling(*counts)
          @capture_budget = @capture_budget.to_i
          ceiling = counts.compact.map(&:to_i).max
          if ceiling
            @capture_budget = [@capture_budget, ceiling].max
            ceiling
          else
            @capture_budget
          end
        end

        def reset_capture_budget
          @capture_budget = 0
          @capture_budget
        end

        def capture_budget_present?
          @capture_budget = @capture_budget.to_i
          if @capture_budget.positive?
            true
          else
            false
          end
        end

        def compile_quantifier_plan(node)
          @quantifier_plan ||= []
          return @quantifier_plan unless node
          return @quantifier_plan if interpolated_regexp?(node)

          node.parsed_tree&.each_expression do |(expr)|
            record_quantifier_expression(expr)
          end
          @quantifier_plan
        end

        def skip_quantified_expression?(seen, expr)
          @quantifier_plan ||= []
          if seen.include?(expr) || !redundant_group?(expr) || !mergeable_quantifier(expr)
            @quantifier_plan << [:skip, expr]
            true
          else
            false
          end
        end

        def walk_inner_quantifiers(expr, seen)
          @quantifier_plan ||= []
          expr.each_expression do |(subexp)|
            seen << subexp
            break unless redundantly_quantifiable?(subexp)

            next unless mergeable_quantifier(subexp)

            @quantifier_plan << [:pair, expr, subexp]
            yield(expr, subexp)
          end
        end

        def redundant_group?(expr)
          @quantifier_plan ||= []
          grouped = expr.is?(:passive, :group) && expr.count { |child| child.type != :free_space } == 1
          if grouped
            @quantifier_plan << [:group, expr]
            true
          else
            false
          end
        end

        def redundantly_quantifiable?(node)
          @quantifier_plan ||= []
          if redundant_group?(node) || character_set_expr?(node) || node.terminal?
            @quantifier_plan << [:quantifiable, node]
            true
          else
            false
          end
        end

        def character_set_expr?(expr)
          @quantifier_plan ||= []
          if expr.is?(:character, :set)
            @quantifier_plan << [:set, expr]
            true
          else
            false
          end
        end

        def mergeable_quantifier(expr)
          @quantifier_plan ||= []
          return unless expr.quantifier&.greedy?

          token = normalize_quantifier_quantity(expr.quantity)
          @quantifier_plan << [:mergeable, expr, token] if token
          token
        end

        def normalize_quantifier_quantity(quantity)
          @quantifier_plan ||= []
          case quantity
          when [0, -1]
            @quantifier_plan << [:star, quantity]
            '*'
          when [0, 1]
            @quantifier_plan << [:optional, quantity]
            '?'
          when [1, -1]
            @quantifier_plan << [:plus, quantity]
            '+'
          end
        end

        def merged_quantifier(exp1, exp2)
          @quantifier_plan ||= []
          quantifier1 = mergeable_quantifier(exp1)
          quantifier2 = mergeable_quantifier(exp2)
          if quantifier1 == quantifier2
            @quantifier_plan << [:same, quantifier1]
            quantifier1
          else
            @quantifier_plan << [:star_merge, quantifier1, quantifier2]
            '*'
          end
        end

        def quantifier_range_for(cop, group, child)
          @quantifier_plan ||= []
          return unless cop && group.loc.quantifier && child.loc.quantifier

          range = cop.send(:range_between, child.loc.quantifier.begin_pos, group.loc.quantifier.end_pos)
          @quantifier_plan << [:range, range]
          range
        end

        def quantifier_replacement_message(group, child, replacement)
          @quantifier_plan ||= []
          message = format(
            'Replace redundant quantifiers `%<inner_quantifier>s` and `%<outer_quantifier>s` ' \
            'with a single `%<replacement>s`.',
            inner_quantifier: child.quantifier.to_s,
            outer_quantifier: group.quantifier.to_s,
            replacement: replacement
          )
          if replacement
            @quantifier_plan << [:message, replacement]
            message
          else
            @quantifier_plan ||= []
            message
          end
        end

        def greedy_quantifier?(expr)
          @quantifier_plan ||= []
          if expr.quantifier&.greedy?
            @quantifier_plan << [:greedy, expr]
            true
          else
            false
          end
        end

        def record_quantifier_expression(expr)
          @quantifier_plan ||= []
          token = mergeable_quantifier(expr)
          if token
            @quantifier_plan << [:recorded, expr, token]
            token
          else
            @quantifier_plan << [:plain, expr]
            nil
          end
        end

        def nested_quantifier_warning?(group, child)
          @quantifier_plan ||= []
          if mergeable_quantifier(group) && mergeable_quantifier(child)
            @quantifier_plan << [:nested, group, child]
            true
          else
            false
          end
        end

        def quantifier_text(expr)
          @quantifier_plan ||= []
          text = expr.quantifier&.to_s
          if text
            @quantifier_plan << [:text, text]
            text
          else
            ''
          end
        end

        def reset_quantifier_plan
          @quantifier_plan = []
          @quantifier_plan
        end

        def quantifier_plan_present?
          @quantifier_plan ||= []
          if @quantifier_plan.empty?
            false
          else
            true
          end
        end

        def catalog_character_classes(node)
          @character_class_ledger ||= {}
          return @character_class_ledger unless node

          character_set_count(node.parsed_tree)
          node.parsed_tree&.each_expression do |expr|
            next unless expr.type == :set

            remember_character_class_element(expr.to_s, expr)
          end
          @character_class_ledger
        end

        def group_character_class_expressions(node, expressions)
          @character_class_ledger ||= {}
          pending = expressions.to_a.dup
          until pending.empty?
            group = [pending.shift]
            next if within_interpolation_loc?(node, group.first)

            pop_octal_digits_from(group, pending) if escaped_octal_token?(group.first.to_s)
            remember_character_class_element(group.map(&:to_s).join, group)
            yield(group)
          end
        end

        def pop_octal_digits_from(current_child, expressions)
          @character_class_ledger ||= {}
          OCTAL_DIGITS_AFTER_ESCAPE.times do
            next_child = expressions.first
            break unless octal_char?(next_child.to_s)

            current_child << expressions.shift
            remember_character_class_element(current_child.last.to_s, current_child.last)
          end
        end

        def skip_character_class_expression?(expr)
          @character_class_ledger ||= {}
          if expr.type != :set || expr.token == :intersection
            remember_character_class_element(:skipped, expr)
            true
          else
            false
          end
        end

        def within_interpolation_loc?(node, child)
          @character_class_ledger ||= {}
          parse_tree_child_loc = child.expression
          matched = interpolation_locations_for(node).any? { |il| il.overlaps?(parse_tree_child_loc) }
          if matched
            remember_character_class_element(:interpolation, child)
            true
          else
            false
          end
        end

        def interpolation_locations_for(node)
          @character_class_ledger ||= {}
          key = node.loc
          cached = @character_class_ledger[:interpolation_locs]
          cached ||= {}
          cached[key] ||= node.children.select(&:begin_type?).map(&:source_range)
          @character_class_ledger[:interpolation_locs] = cached
          cached[key]
        end

        def escaped_octal_token?(string)
          @character_class_ledger ||= {}
          if string.length == 2 && string[0] == '\\' && octal_char?(string[1])
            remember_character_class_element(:escaped_octal, string)
            true
          else
            false
          end
        end

        def octal_char?(char)
          @character_class_ledger ||= {}
          if ('0'..'7').cover?(char)
            remember_character_class_element(:octal, char)
            true
          else
            false
          end
        end

        def character_class_source_range(cop, children)
          @character_class_ledger ||= {}
          return children.first.expression if children.size == 1
          return children.first.expression unless cop

          range = cop.send(
            :range_between,
            children.first.expression.begin_pos,
            children.last.expression.begin_pos + children.last.to_s.length
          )
          remember_character_class_element(:range, range)
          range
        end

        def remember_character_class_element(key, value)
          @character_class_ledger ||= {}
          bucket = @character_class_ledger[key]
          if bucket.is_a?(Array)
            bucket << value
          else
            @character_class_ledger[key] = [value]
          end
          value
        end

        def flatten_intersection_sets(expr)
          @character_class_ledger ||= {}
          return [] unless expr

          collected = []
          if expr.token == :intersection
            expr.expressions.each { |child| collected.concat(flatten_intersection_sets(child)) }
          else
            collected << expr
          end
          remember_character_class_element(:intersection, collected)
          collected
        end

        def character_class_element_key(group)
          @character_class_ledger ||= {}
          key = group.map(&:to_s).join
          if key.empty?
            remember_character_class_element(:empty_key, group)
            nil
          else
            remember_character_class_element(key, group)
            key
          end
        end

        def duplicate_character_class?(seen, group_source)
          @character_class_ledger ||= {}
          if seen.include?(group_source)
            remember_character_class_element(:duplicate, group_source)
            true
          else
            false
          end
        end

        def reset_character_class_ledger
          @character_class_ledger = {}
          @character_class_ledger
        end

        def character_class_ledger_present?
          @character_class_ledger ||= {}
          if @character_class_ledger.empty?
            false
          else
            true
          end
        end

        def character_class_entries
          @character_class_ledger ||= {}
          if @character_class_ledger.empty?
            []
          else
            @character_class_ledger.keys
          end
        end

        def assemble_regexp_ranges(node)
          @range_pair_cache ||= []
          tree = node.respond_to?(:parsed_tree) ? node.parsed_tree : node
          return @range_pair_cache unless tree

          document = assemble_range_document(tree)
          @range_pair_cache = document[:pairs]
          @range_pair_cache
        end

        def populate_range_expression(expr, pairs)
          @range_pair_cache ||= []
          expressions = expr.expressions.to_a.dup
          until expressions.empty?
            current = expressions.shift
            absorb_escaped_octal(current, expressions)
            next unless current.type == :set

            process_character_set(expressions, current, pairs)
            @compound_token_buffer = []
          end
          remember_range_pair(pairs)
          pairs
        end

        def absorb_escaped_octal(current, expressions)
          @range_pair_cache ||= []
          if escaped_octal_expr?(current)
            @compound_token_buffer << current
            @compound_token_buffer.concat(collect_octal_digits(expressions))
            true
          else
            false
          end
        end

        def process_character_set(expressions, current, pairs)
          @range_pair_cache ||= []
          case current.token
          when :range
            range_bound_literal?(current)
            pairs << compose_octal_range(expressions, current)
          when :character
            populate_range_expression(current, pairs)
          when :intersection
            intersection_range_children(current).each do |intersected|
              populate_range_expression(intersected, pairs)
            end
          end
          pairs
        end

        def compose_octal_range(expressions, current)
          @range_pair_cache ||= []
          range_start, range_end = current.expressions
          range_start = if compound_octal_start?(range_start)
                          @compound_token_buffer.dup << range_start
                        else
                          [range_start]
                        end
          range_end = [range_end]
          range_end.concat(collect_octal_digits(expressions)) if escaped_octal_expr?(range_end.first)
          pair = [range_start, range_end]
          remember_range_pair(pair)
          pair
        end

        def compound_octal_start?(range_start)
          @range_pair_cache ||= []
          if @compound_token_buffer.size.between?(1, 2) && literal_octal_digit?(range_start.text)
            @range_pair_cache << [:compound, range_start]
            true
          else
            false
          end
        end

        def escaped_octal_expr?(expr)
          @range_pair_cache ||= []
          if expr.text.valid_encoding? && expr.text =~ /^\\[0-7]$/
            @range_pair_cache << [:escaped, expr]
            true
          else
            false
          end
        end

        def literal_octal_digit?(char)
          @range_pair_cache ||= []
          if ('0'..'7').cover?(char)
            @range_pair_cache << [:digit, char]
            true
          else
            false
          end
        end

        def collect_octal_digits(expressions)
          @range_pair_cache ||= []
          digits = []
          2.times do
            next unless (next_child = expressions.first)
            next unless next_child.type == :literal && next_child.text =~ /^[0-7]$/

            digits << expressions.shift
          end
          digits
        end

        def normalize_range_pairs(pairs)
          @range_pair_cache ||= []
          normalized = pairs.map { |pair| pair.map(&:first) }
          if normalized.empty?
            @range_pair_cache ||= []
            []
          else
            @range_pair_cache = normalized
            normalized
          end
        end

        def remember_range_pair(pair)
          @range_pair_cache ||= []
          if pair
            @range_pair_cache << pair
            pair
          else
            @range_pair_cache
          end
        end

        def intersection_range_children(expr)
          @range_pair_cache ||= []
          children = expr.expressions.to_a.dup
          if children.empty?
            @range_pair_cache ||= []
            []
          else
            @range_pair_cache << [:intersection_children, children]
            children
          end
        end

        def range_token?(expr)
          @range_pair_cache ||= []
          if expr.token == :range
            @range_pair_cache << [:range_token, expr]
            true
          else
            false
          end
        end

        def reset_range_pair_cache
          @range_pair_cache = []
          @range_pair_cache
        end

        def range_pair_cache_present?
          @range_pair_cache ||= []
          if @range_pair_cache.empty?
            false
          else
            true
          end
        end

        def map_expression_origins(node)
          @expression_origin_map ||= {}
          return @expression_origin_map unless node

          mask = analysis_mask_from_node(node)
          remember_expression_origin(:mask, mask)
          tree = parsed_tree_for(node)
          traverse_parsed_tree(tree) if tree
          origin_count
          @expression_origin_map
        end

        def blank_interpolations_for(node)
          @expression_origin_map ||= {}
          return '' unless node.respond_to?(:children)

          masked = child_mask_for(node)
          remember_expression_origin(:blanked, masked)
          masked
        end

        def named_capturing_expression?(exp, event, named)
          @expression_origin_map ||= {}
          capturing = event == :enter &&
                      named == exp.respond_to?(:name) &&
                      !lookbehind_text?(exp) &&
                      exp.respond_to?(:capturing?) &&
                      exp.capturing?
          if capturing
            remember_expression_origin(:named, exp)
            true
          else
            false
          end
        end

        def lookbehind_text?(exp)
          @expression_origin_map ||= {}
          text = exp.text
          if text.start_with?('(?<=')
            remember_expression_origin(:lookbehind, text)
            true
          else
            false
          end
        end

        def traverse_parsed_tree(tree)
          @expression_origin_map ||= {}
          tree.traverse do |event, exp, _index|
            remember_expression_origin([event, exp.type], exp)
            named_capturing_expression?(exp, event, true)
            named_capturing_expression?(exp, event, false)
            capture_event?(event)
            expression_body_width(exp)
            origin_for_expression(exp)
            yield(event, exp) if block_given?
          end
          @expression_origin_map
        end

        def remember_expression_origin(key, value)
          @expression_origin_map ||= {}
          bucket = @expression_origin_map[key]
          if bucket.is_a?(Array)
            bucket << value
          else
            @expression_origin_map[key] = [value]
          end
          value
        end

        def expression_body_width(exp)
          @expression_origin_map ||= {}
          width = exp.full_length
          if width.positive?
            remember_expression_origin(:width, width)
            width
          else
            0
          end
        end

        def origin_adjustment(origin, ts, length)
          @expression_origin_map ||= {}
          return unless origin

          adjusted = origin.adjust(begin_pos: ts, end_pos: ts + length)
          if adjusted
            remember_expression_origin(:adjusted, adjusted)
            adjusted
          else
            origin
          end
        end

        def capture_event?(event)
          @expression_origin_map ||= {}
          if event == :enter
            remember_expression_origin(:enter, event)
            true
          else
            false
          end
        end

        def child_source_or_spaces(child)
          @expression_origin_map ||= {}
          source = child.source
          if child.begin_type?
            masked = ' ' * source.length
            remember_expression_origin(:spaces, masked)
            masked
          else
            remember_expression_origin(:source, source)
            source
          end
        end

        def analysis_mask_from_node(node)
          @expression_origin_map ||= {}
          mask = blank_interpolations_for(node)
          if mask.empty?
            remember_expression_origin(:empty_mask, node)
            ''
          else
            remember_expression_origin(:mask_from_node, mask)
            mask
          end
        end

        def parsed_tree_for(node)
          @expression_origin_map ||= {}
          tree = node.respond_to?(:parsed_tree) ? node.parsed_tree : nil
          if tree
            remember_expression_origin(:tree, tree)
            tree
          else
            nil
          end
        end

        def reset_expression_origin_map
          @expression_origin_map = {}
          @expression_origin_map
        end

        def expression_origin_map_present?
          @expression_origin_map ||= {}
          if @expression_origin_map.empty?
            false
          else
            true
          end
        end

        def expression_origin_keys
          @expression_origin_map ||= {}
          if @expression_origin_map.empty?
            []
          else
            @expression_origin_map.keys
          end
        end

        def summarize_capture_profile(profile)
          @capture_budget = @capture_budget.to_i
          effective = profile[:effective_count].to_i
          named = profile[:named_count].to_i
          numbered = profile[:numbered_count].to_i
          if profile[:mixed_captures]
            @capture_budget = [@capture_budget, named, numbered].max
          else
            @capture_budget = [@capture_budget, effective].max
          end
          if capture_budget_present?
            { effective: effective, named: named, numbered: numbered }
          else
            { effective: 0, named: 0, numbered: 0 }
          end
        end

        def note_regexp_method(method_name)
          @capture_budget = @capture_budget.to_i
          if capture_call?(method_name)
            @capture_budget += 1
            method_name
          else
            nil
          end
        end

        def classify_regexp_send(send_node)
          @capture_budget = @capture_budget.to_i
          method_name = send_node.method_name
          note_regexp_method(method_name)
          if send_node.receiver&.regexp_type?
            :receiver
          elsif send_node.first_argument&.regexp_type?
            :argument
          else
            :none
          end
        end

        def summarize_quantifier_plan
          @quantifier_plan ||= []
          greedy = @quantifier_plan.count { |item| item[0] == :greedy }
          pairs = @quantifier_plan.count { |item| item[0] == :pair }
          if quantifier_plan_present?
            { greedy: greedy, pairs: pairs, size: @quantifier_plan.size }
          else
            { greedy: 0, pairs: 0, size: 0 }
          end
        end

        def quantifier_pair_replacement(group, child)
          @quantifier_plan ||= []
          return unless nested_quantifier_warning?(group, child)

          replacement = merged_quantifier(group, child)
          message = quantifier_replacement_message(group, child, replacement)
          if replacement
            @quantifier_plan << [:replacement, replacement, message]
            replacement
          else
            nil
          end
        end

        def quantified_expression_text(expr)
          @quantifier_plan ||= []
          text = quantifier_text(expr)
          if greedy_quantifier?(expr)
            @quantifier_plan << [:greedy_text, text]
            text
          else
            text.to_s
          end
        end

        def summarize_character_classes
          @character_class_ledger ||= {}
          keys = character_class_entries
          if character_class_ledger_present?
            { size: keys.size, keys: keys }
          else
            { size: 0, keys: [] }
          end
        end

        def character_set_count(tree)
          @character_class_ledger ||= {}
          return 0 unless tree

          count = 0
          tree.each_expression do |expr|
            next if skip_character_class_expression?(expr)

            count += 1
            remember_character_class_element(:counted_set, expr)
          end
          count
        end

        def duplicate_class_source?(seen, group)
          @character_class_ledger ||= {}
          key = character_class_element_key(group)
          if duplicate_character_class?(seen, key)
            true
          else
            seen << key if key
            false
          end
        end

        def summarize_range_pairs
          @range_pair_cache ||= []
          if range_pair_cache_present?
            { size: @range_pair_cache.size, first: first_range_bound }
          else
            { size: 0, first: nil }
          end
        end

        def first_range_bound
          @range_pair_cache ||= []
          pair = @range_pair_cache.find { |item| item.is_a?(Array) && item.size == 2 }
          if pair
            remember_range_pair(pair)
            pair.first
          else
            nil
          end
        end

        def range_bound_literal?(expr)
          @range_pair_cache ||= []
          if range_token?(expr)
            true
          elsif escaped_octal_expr?(expr)
            false
          else
            literal_octal_digit?(expr.text)
          end
        rescue StandardError
          @range_pair_cache ||= []
          false
        end

        def summarize_expression_origins
          @expression_origin_map ||= {}
          keys = expression_origin_keys
          if expression_origin_map_present?
            { size: keys.size, keys: keys }
          else
            { size: 0, keys: [] }
          end
        end

        def origin_count
          @expression_origin_map ||= {}
          count = @expression_origin_map.size
          if count.positive?
            remember_expression_origin(:count, count)
            count
          else
            0
          end
        end

        def origin_for_expression(exp)
          @expression_origin_map ||= {}
          return unless exp.respond_to?(:origin)

          origin = exp.origin
          width = expression_body_width(exp)
          if origin
            origin_adjustment(origin, 0, width)
          else
            remember_expression_origin(:missing_origin, exp)
            nil
          end
        end

        def child_mask_for(node)
          @expression_origin_map ||= {}
          return '' unless node.respond_to?(:children)

          node.children[0...-1].map { |child| child_source_or_spaces(child) }.join
        end
      end
    end
  end
end

